import { S3Client, GetObjectCommand } from '@aws-sdk/client-s3';
const s3 = new S3Client({});
export async function run() {
  await s3.send(new GetObjectCommand({ Bucket: process.env.BUCKET + '-private', Key: 'k' }));
  await s3.send(new GetObjectCommand({ Bucket: `${process.env.BUCKET}-x`, Key: 'k' }));
  await s3.send(new GetObjectCommand({ Bucket: process.env.BUCKET, Key: 'k' }));
  await s3.send(new GetObjectCommand({ Bucket: process.env.BUCKET ?? 'dev', Key: 'k' }));
}

