package main

import (
	"context"
	"os"
	"github.com/aws/aws-sdk-go-v2/aws"
	"github.com/aws/aws-sdk-go-v2/service/sns"
)

func run(ctx context.Context, c *sns.Client) {
	c.Publish(ctx, &sns.PublishInput{TopicArn: aws.String(os.Getenv("X") + "-y")})
	c.Publish(ctx, &sns.PublishInput{TopicArn: aws.String(os.Getenv("X"))})
}
